css:
/* ==== INTERFACE ====
   token  --bg #18191B        深墨灰底色（汉简漆器与石室藏书夜读之底）
   token  --text #E7E8E4      正文及标头默认浅墨色
   token  --muted #8F9496     次要辅助说明、纪年刻度与元数据说明
   token  --rule #35393D      纪年轴线、列传断代刻度与单向参考基准线
   token  --focus #DC3826     朱砂焦点（唯一操作锚点、当前选定传记）
   token  --primary #D6A461   主干纪事标色（全页主色：帝王本纪与核心世家纪年）
   token  --fs-h1 34px        篇章总题
   token  --fs-h2 22px        纪传章次与列传人名分题
   token  --fs-lead 19px      太史公曰题解与叙事导语
   token  --fs-body 18px      正史本纪列传叙事正文
   token  --fs-sec 16px       世家年表注记与人物生卒纪事
   token  --fs-label 15px     十二本纪/三十世家/七十列传分目及控制标签
   token  --fs-tick 13px      纪年刻度与纯数字年号标尺
   版心   1488×844            #stage 已含 padding
   论点   《史记》是究天人之际的史家绝唱，视觉系统必须以深墨竹木漆底构建庄严肃穆的石室金匮感，由主干金赭贯穿全纪，辅以极克制的朱砂笔圈点当下关键人物。
   材质   生漆墨木：取自汉代简牍黑漆底板与朱砂校勘批注，无发光无现代毛玻璃。
   签名   太史公笔法朱砂圈点：纵向年表轴线上的朱砂圆点与高反差金赭纪事带形成历史断代锚。
   禁令   禁止任何卡片底色块堆叠；禁止在深底上使用半透明白色光晕边框；除 --focus 朱砂外禁止引入多相饱和强调色。
   修订   原本会选竹简泛黄浅米底，但易落入俗套奶油纸张且投影易发白；改用西汉漆器深墨灰底配高对比赭金与朱砂，既强化史书庄严又彻底拉开明度反差。
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  --bg: #18191B;
  --text: #E7E8E4;
  --muted: #8F9496;
  --rule: #35393D;
  --focus: #DC3826;
  --primary: #D6A461;

  --font-sans: "Noto Serif CJK SC", "AR PL UMing CN", "AR PL SungtiL GB", serif;
  --font-display: "Noto Serif Display", "Noto Serif CJK SC", "AR PL SungtiL GB", serif;
  --font-mono: "Noto Sans Mono", "WenQuanYi Zen Hei Mono", monospace;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --lh-tight: 1.25;
  --lh-base: 1.55;
  --lh-loose: 1.75;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
